import org.apache.commons.cli.help.TextHelpAppendable;
import org.apache.commons.cli.help.TableDefinition;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;

public class AdjustTableFormatTests {
    @Test
    public void testAdjustTableFormat() {
        // Setup
        final TextHelpAppendable appendable = new TextHelpAppendable(null);
        final TableDefinition table = new TableDefinition("caption", new ArrayList<>(), new ArrayList<>(), new ArrayList<>());

        // Execute
        final TableDefinition adjustedTable = appendable.adjustTableFormat(table);

        // Verify
        assertEquals(table, adjustedTable);
    }
